package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

type stat struct {
	sites     int
	testSites int
	callers   map[string]bool
	pkgs      map[string]bool
}

func main() {
	root := os.Args[1]
	cfg := &packages.Config{
		Mode:  packages.NeedName | packages.NeedFiles | packages.NeedSyntax | packages.NeedTypes | packages.NeedTypesInfo | packages.NeedDeps | packages.NeedImports,
		Dir:   root,
		Tests: true,
	}
	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		panic(err)
	}
	stats := map[*types.Func]*stat{}
	seenPkg := map[string]bool{}
	for _, p := range pkgs {
		if seenPkg[p.ID] {
			continue
		}
		seenPkg[p.ID] = true
		fset := p.Fset
		for _, f := range p.Syntax {
			// track enclosing func
			var enclosing []string
			var cur string
			ast.Inspect(f, func(n ast.Node) bool {
				switch x := n.(type) {
				case *ast.FuncDecl:
					name := x.Name.Name
					if x.Recv != nil {
						name = "recv." + name
					}
					enclosing = append(enclosing, cur)
					cur = p.PkgPath + "." + name
					_ = enclosing
				case *ast.CallExpr:
					var id *ast.Ident
					switch fn := x.Fun.(type) {
					case *ast.Ident:
						id = fn
					case *ast.SelectorExpr:
						id = fn.Sel
					}
					if id == nil {
						return true
					}
					obj := p.TypesInfo.Uses[id]
					if obj == nil {
						obj = p.TypesInfo.Defs[id]
					}
					fnObj, ok := obj.(*types.Func)
					if !ok {
						return true
					}
					pos := fset.Position(fnObj.Pos())
					if !strings.Contains(pos.Filename, "/internal/") {
						return true
					}
					s := stats[fnObj]
					if s == nil {
						s = &stat{callers: map[string]bool{}, pkgs: map[string]bool{}}
						stats[fnObj] = s
					}
					callPos := fset.Position(id.Pos())
					s.sites++
					if strings.HasSuffix(callPos.Filename, "_test.go") {
						s.testSites++
					}
					s.callers[cur+"|"+callPos.Filename]:= true
					s.pkgs[p.PkgPath] = true
				}
				return true
			})
		}
	}
	type row struct {
		name string
		s    *stat
		pos  token.Position
	}
	var rows []row
	for fn, s := range stats {
		var fset *token.FileSet
		for _, p := range pkgs {
			fset = p.Fset
			break
		}
		rows = append(rows, row{fullName(fn), s, fset.Position(fn.Pos())})
	}
	sort.Slice(rows, func(i, j int) bool { return rows[i].s.sites > rows[j].s.sites })
	for i, r := range rows {
		if i > 40 {
			break
		}
		fmt.Printf("%3d sites (%d in tests) callers=%d  %s  %s:%d\n", r.s.sites, r.s.testSites, len(r.s.callers), r.name, r.pos.Filename, r.pos.Line)
	}
}

func fullName(f *types.Func) string {
	sig := f.Signature()
	if sig.Recv() != nil {
		return sig.Recv().Type().String() + "." + f.Name()
	}
	if f.Pkg() != nil {
		return f.Pkg().Path() + "." + f.Name()
	}
	return f.Name()
}
EOF
